namespace Twain.Core.EditSummaries;

/// <summary>
/// Builds an article edit summary from the configured summary,
/// processing contributions, and section-edit preferences.
/// </summary>
public static class EditSummaryBuilder
{
    /// <summary>
    /// Builds the edit summary for the supplied article.
    /// </summary>
    /// <param name="configuredSummary">
    /// The edit summary selected or entered by the user.
    /// </param>
    /// <param name="articleSummary">
    /// The summary generated by article-processing operations.
    /// </param>
    /// <param name="originalArticleText">
    /// The article text before processing.
    /// </param>
    /// <param name="currentArticleText">
    /// The final article text.
    /// </param>
    /// <param name="includeSectionSummary">
    /// Whether automatic section summaries are enabled.
    /// </param>
    /// <returns>
    /// The combined edit summary.
    /// </returns>
    public static string Build(
        string configuredSummary,
        string articleSummary,
        string originalArticleText,
        string currentArticleText,
        bool includeSectionSummary)
    {
        ArgumentNullException.ThrowIfNull(configuredSummary);
        ArgumentNullException.ThrowIfNull(articleSummary);
        ArgumentNullException.ThrowIfNull(originalArticleText);
        ArgumentNullException.ThrowIfNull(currentArticleText);

        string summary =
            Summary.AppendArticleSummary(
                configuredSummary,
                articleSummary);

        if (includeSectionSummary)
        {
            summary = AddModifiedSections(
                summary,
                originalArticleText,
                currentArticleText);
        }

        return summary;
    }

    /// <summary>
    /// Builds an edit summary from independently collected processing
    /// contributions using the specified formatting policy.
    /// </summary>
    /// <param name="configuredSummary">
    /// The default summary selected or entered by the user.
    /// </param>
    /// <param name="collector">
    /// The processing contributions collected for the article.
    /// </param>
    /// <param name="policy">
    /// The rules governing summary formatting and ordering.
    /// </param>
    /// <param name="originalArticleText">
    /// The original article text.
    /// </param>
    /// <param name="currentArticleText">
    /// The article text after processing.
    /// </param>
    /// <param name="includeSectionSummary">
    /// Whether automatic section summaries are enabled.
    /// </param>
    /// <returns>
    /// The assembled summary and its validation information.
    /// </returns>
    public static EditSummaryResult Build(
        string configuredSummary,
        EditSummaryCollector collector,
        EditSummaryPolicy policy,
        string originalArticleText,
        string currentArticleText,
        bool includeSectionSummary)
    {
        ArgumentNullException.ThrowIfNull(configuredSummary);
        ArgumentNullException.ThrowIfNull(collector);
        ArgumentNullException.ThrowIfNull(policy);
        ArgumentNullException.ThrowIfNull(originalArticleText);
        ArgumentNullException.ThrowIfNull(currentArticleText);

        var contributions = collector.Contributions
            .OrderBy(contribution =>
                policy.GetCategoryPolicy(
                    contribution.Category).DisplayOrder)
            .ThenBy(contribution => contribution.Description)
            .ToList();

        var descriptions = new List<string>();

        if (!string.IsNullOrWhiteSpace(configuredSummary))
        {
            descriptions.Add(configuredSummary);
        }

        foreach (EditSummaryContribution contribution in contributions)
        {
            if (string.IsNullOrWhiteSpace(contribution.Description))
            {
                continue;
            }

            if (policy.RemoveDuplicates &&
                descriptions.Contains(
                    contribution.Description,
                    StringComparer.Ordinal))
            {
                continue;
            }

            descriptions.Add(contribution.Description);
        }

        string summary = string.Join(
            policy.Separator,
            descriptions);

        if (includeSectionSummary)
        {
            summary = AddModifiedSections(
                summary,
                originalArticleText,
                currentArticleText);
        }

        int byteLength = Encoding.UTF8.GetByteCount(summary);

        return new EditSummaryResult
        {
            Text = summary,
            ByteLength = byteLength,
            MaximumBytes = policy.MaximumBytes,
            WasCompressed = false,
            IsValid =
                byteLength <= policy.MaximumBytes &&
                Summary.IsCorrect(summary)
        };
    }

    /// <summary>
    /// Adds a description of the modified article sections to an edit summary.
    /// </summary>
    /// <remarks>
    /// A single modified section uses the traditional MediaWiki section prefix.
    /// Multiple modified sections use a descriptive summary instead.
    /// </remarks>
    private static string AddModifiedSections(
        string summary,
        string originalArticleText,
        string currentArticleText)
    {
        IReadOnlyList<string> modifiedSections =
            Summary.GetModifiedSections(
                originalArticleText,
                currentArticleText);

        if (modifiedSections.Count == 0)
        {
            return summary;
        }

        // Preserve the traditional MediaWiki section prefix.
        if (modifiedSections.Count == 1)
        {
            string section = modifiedSections[0];

            return section == "top"
                ? summary
                : $"/* {section} */ {summary}".TrimEnd();
        }

        string description;

        if (modifiedSections.Count == 2)
        {
            description =
                $"Updated {modifiedSections[0]} and {modifiedSections[1]}";
        }
        else
        {
            description = "Updated multiple sections";
        }

        return string.IsNullOrWhiteSpace(summary)
            ? description
            : $"{description}; {summary}";
    }
}